recess_margin = 6;

slot_len = 70;
slot_w = 4;
slot_depth = recess_depth + 1;

module frustum_box(size_bottom=[10,10,10], size_top=[12,12,10], h=10){
    hull(){
        translate([0,0,0]) cube([size_bottom[0], size_bottom[1], 0.01], center=true);
        translate([0,0,h]) cube([size_top[0], size_top[1], 0.01], center=true);
    }
}

module outer_shell(){
    union(){
        frustum_box(
            size_bottom=[L - 2*wall_taper, W - 2*wall_taper, H],
            size_top=[L, W, H],
            h=H
        );
        translate([0,0,H - flange_thk/2])
            cube([L + 2*flange_overhang, W + 2*flange_overhang, flange_thk], center=true);
    }
}

module inner_cavity(){
    frustum_box(
        size_bottom=[(L - 2*wall_taper) - 2*bottom_margin, (W - 2*wall_taper) - 2*bottom_margin, H],
        size_top=[L - 2*bottom_margin, W - 2*bottom_margin, H],
        h=H - flange_thk
    );
}

module recessed_panel_cut(){
    translate([0,0,H - flange_thk - recess_depth/2])
        cube([L - 2*recess_margin, W - 2*recess_margin, recess_depth], center=true);
}

module slot_cut(){
    translate([0,0,H - flange_thk - recess_depth + slot_depth/2])
        cube([slot_len, slot_w, slot_depth], center=true);
}

difference(){
    outer_shell();
    translate([0,0,(H - flange_thk)/2])
        inner_cavity();
    recessed_panel_cut();
    slot_cut();
}

$fn=96;

L = 100;
W = 40;
H = 24;

cut_r = 16;
cut_z = 0;

prong_len = 40;
prong_gap = 14;
prong_thk = 8;
prong_h = 18;

hole_d = 6;
hole_offset = 38;

chamfer = 3;

module chamfered_box(size=[10,10,10], c=2){
    sx=size[0]; sy=size[1]; sz=size[2];
    intersection(){
        cube([sx,sy,sz], center=true);
        union(){
            cube([sx-2*c, sy, sz], center=true);
            cube([sx, sy-2*c, sz], center=true);
            cube([sx, sy, sz-2*c], center=true);
            rotate([0,0,45]) cube([sx*1.2, sy-2*c, sz-2*c], center=true);
            rotate([0,0,45]) cube([sx-2*c, sy*1.2, sz-2*c], center=true);
            rotate([0,0,45]) cube([sx-2*c, sy-2*c, sz*1.2], center=true);
        }
    }
}

module prong(xc, yc){
    translate([xc, yc, 0])
        chamfered_box([prong_len, prong_thk, prong_h], c=chamfer);
}

module body(){
    union(){
        chamfered_box([L, W, H], c=chamfer);

        // Two prongs extending from +X side
        prong(L/2 + prong_len/2 - chamfer,  (prong_gap/2 + prong_thk/2));
        prong(L/2 + prong_len/2 - chamfer, -(prong_gap/2 + prong_thk/2));
    }
}

module internal_cutout(){
    // Large semicircular internal cutout (cylindrical along X), open to -Y side
    translate([0, -W/2 + cut_r + 2, cut_z])
        rotate([0,90,0])
            cylinder(h=L + prong_len + 10, r=cut_r, center=true);
}

module fork_opening(){
    // Remove material between prongs to create fork opening
    translate([L/2 + prong_len/2 - chamfer, 0, 0])
        cube([prong_len + 2, prong_gap, prong_h + 2], center=true);
}

module end_hole(xpos){
    // Through-hole along Y, appears diamond-shaped when viewed at angle by rotating square profile
    translate([xpos, 0, 0])
        rotate([90,0,0])
            rotate([0,0,45])
                cylinder(h=W + 20, r=hole_d/2, center=true, $fn=4);
}

difference(){
    body();
    internal_cutout();
    fork_opening();
    end_hole(-hole_offset);
    end_hole( hole_offset);
}

$fn=96;

plate_th = 6;

body_len = 120;
body_w   = 30;

flange_len = 40;
flange_w   = 60;

total_len = body_len + flange_len;

chamfer = 10;

hole_d = 6.5;
hole_edge_x = 10;
hole_edge_y = 10;

emboss_depth = 0.8;
emboss_th = 1.2;

module stepped_outline_2d() {
    union() {
        translate([-total_len/2, -body_w/2]) square([body_len, body_w], center=false);
        translate([ total_len/2 - flange_len, -flange_w/2]) square([flange_len, flange_w], center=false);
    }
}

module chamfered_end_2d() {
    // subtract two right triangles at the far (non-flange) end corners
    union() {
        // top corner
        translate([-total_len/2, body_w/2 - chamfer])
            polygon(points=[[0,0],[chamfer,0],[0,chamfer]]);
        // bottom corner
        translate([-total_len/2, -body_w/2])
            polygon(points=[[0,0],[chamfer,0],[0,chamfer]]);
    }
}

module base_plate() {
    difference() {
        linear_extrude(height=plate_th, center=true)
            difference() {
                stepped_outline_2d();
                chamfered_end_2d();
            }

        // flange holes
        for (sy = [-1, 1]) {
            translate([ total_len/2 - hole_edge_x, sy*(flange_w/2 - hole_edge_y), 0])
                cylinder(h=plate_th+2, d=hole_d, center=true);
        }
    }
}

module v_feature_2d(len=34, w=18, t=emboss_th) {
    // V/arrow made from two rotated rectangles
    union() {
        translate([0,0]) rotate(30) square([len, t], center=true);
        translate([0,0]) rotate(-30) square([len, t], center=true);
        // small tail
        translate([-len*0.18,0]) square([len*0.25, t], center=true);
    }
}

module face_features(mode="recess") {
    // mode: "recess" subtracts; "emboss" adds
    zpos = plate_th/2 - emboss_depth/2;

    // positions along length: one on body, one on flange
    positions = [
        [-total_len/2 + 55, 0, 0],
        [ total_len/2 - 20, 0, 0]
    ];

    if (mode == "recess") {
        for (p = positions) {
            translate([p[0], p[1],  zpos])
                linear_extrude(height=emboss_depth, center=true)
                    v_feature_2d();
            translate([p[0], p[1], -zpos])
                linear_extrude(height=emboss_depth, center=true)
                    v_feature_2d();
        }
    } else {
        for (p = positions) {
            translate([p[0], p[1],  plate_th/2 + emboss_depth/2])
                linear_extrude(height=emboss_depth, center=true)
                    v_feature_2d();
            translate([p[0], p[1], -plate_th/2 - emboss_depth/2])
                linear_extrude(height=emboss_depth, center=true)
                    v_feature_2d();
        }
    }
}

difference() {
    base_plate();
    face_features("recess");
}

$fn=64;

L = 1.4;
W = 0.9;
H = 0.3;

mid_len = 0.92;
cap_len = (L - mid_len)/2;

r_mid = 0.11;
r_fin = 0.135;

fin_count = 14;
fin_th = 0.018;

tab_count = 8;
tab_w = 0.06;
tab_t = 0.03;
tab_h = 0.06;

nub_r = 0.035;
nub_len = 0.06;

module fin_ring(zpos){
    translate([0,0,zpos])
        cylinder(h=fin_th, r=r_fin, center=true);
}

module ribbed_mid(){
    union(){
        cylinder(h=mid_len, r=r_mid, center=true);
        for(i=[0:fin_count-1]){
            z = -mid_len/2 + (i+0.5)*mid_len/fin_count;
            fin_ring(z);
        }
    }
}

module end_cap(zc, flip=1){
    translate([0,0,zc])
    union(){
        cylinder(h=cap_len, r=0.16, center=true, $fn=6);
        translate([0,0,flip*(cap_len*0.15)])
            cylinder(h=cap_len*0.7, r=0.145, center=true, $fn=6);
    }
}

module radial_tab(zpos, ang){
    translate([0,0,zpos])
    rotate([0,0,ang])
    translate([r_fin + tab_t/2, 0, 0])
        cube([tab_t, tab_w, tab_h], center=true);
}

module tabs_along(){
    union(){
        for(i=[0:tab_count-1]){
            z = -mid_len/2 + (i+0.5)*mid_len/tab_count;
            radial_tab(z, 0);
            radial_tab(z, 180);
        }
    }
}

module side_nub(){
    zpos = L/2 - cap_len*0.65;
    translate([0,0,zpos])
    translate([r_fin + nub_len/2, 0, 0])
    rotate([0,90,0])
        cylinder(h=nub_len, r=nub_r, center=true);
}

module part(){
    union(){
        ribbed_mid();
        end_cap(-L/2 + cap_len/2, flip=-1);
        end_cap( L/2 - cap_len/2, flip= 1);
        tabs_along();
        side_nub();
    }
}

scale([W/(2*(r_fin + tab_t)), H/(2*(r_fin + tab_t)), 1])
    part();

$fn=96;

plate_w = 0.1;
plate_t = 0.0;

boss_d = 0.06;
boss_h = 0.0;

hex_af = 0.02;
hex_h = 0.0;

hole_d = 0.01;

concave_r = 0.06;
concave_offset = 0.03;

module concave_plate_2d(w, r, off){
    difference(){
        square([w,w], center=true);
        for(a=[0,90,180,270]){
            rotate(a)
                translate([w/2 + off, 0])
                    circle(r=r);
        }
    }
}

module corner_holes_2d(w, d, inset){
    for(sx=[-1,1], sy=[-1,1]){
        translate([sx*(w/2 - inset), sy*(w/2 - inset)])
            circle(d=d);
    }
}

module hex_prism(af, h){
    r = af / sqrt(3);
    cylinder(h=h, r=r, $fn=6);
}

module mounting_plate(){
    difference(){
        linear_extrude(height=plate_t, center=true)
            concave_plate_2d(plate_w, concave_r, concave_offset);
        linear_extrude(height=plate_t + 0.02, center=true)
            corner_holes_2d(plate_w, hole_d, inset=0.015);
    }
}

module boss(){
    cylinder(h=boss_h, d=boss_d, center=true);
}

module drive_hex(){
    translate([0,0,(boss_h/2) + (hex_h/2)])
        hex_prism(hex_af, hex_h);
}

union(){
    mounting_plate();
    boss();
    drive_hex();
}

