module cross_arms(){
    union(){
        chamfered_bar(2*arm_len, arm_w, thk, chamfer);
        rotate([0,0,90]) chamfered_bar(2*arm_len, arm_w, thk, chamfer);
    }
}

module center_boss(){
    hull(){
        cylinder(h=center_thk, r=center_r, center=true);
        cylinder(h=thk, r=center_r+1.2, center=true);
    }
}

union(){
    cross_arms();
    center_boss();
