gap_w = 0.022;
gap_t = 0.004;

// Small step at tab tip to form latch lip
lip_len = 0.006;
lip_drop = 0.003;

module base_frame() {
  difference() {
    cube([L, W, T], center=true);
    cube([window_L, window_W, T + 2*eps], center=true);
  }
}

module end_block() {
  translate([L/2 - end_block_L/2, 0, (end_block_T - T)/2])
    cube([end_block_L, W, end_block_T], center=true);
}

module cantilever_tab() {
  // Anchor near inner edge of end block, extending into window
  anchor_x = (L/2 - end_block_L) + frame_wall/2;
  translate([anchor_x, 0, 0]) {
    // Main tab
    rotate([0, tab_angle, 0])
      translate([-tab_len/2, 0, (T/2 + tab_t/2 - 0.001)])
        cube([tab_len, tab_w, tab_t], center=true);

    // Lip/step at tip
    rotate([0, tab_angle, 0])
      translate([-tab_len + lip_len/2, 0, (T/2 + tab_t/2 - 0.001) - lip_drop])
        cube([lip_len, tab_w*0.9, tab_t], center=true);
  }
}

module undercut_gap() {
  // Carve a gap under the tab to suggest undercut-like feature
  anchor_x = (L/2 - end_block_L) + frame_wall/2;
  translate([anchor_x, 0, 0]) {
    rotate([0, tab_angle, 0])
      translate([-gap_len/2 - 0.006, 0, (T/2 + gap_t/2 - 0.001)])
        cube([gap_len, gap_w, gap_t], center=true);
  }
}

difference() {
  union() {
    base_frame();
    end_block();
    cantilever_tab();
  }
  undercut_gap();
}

$fn=64;

plate_th = 2;

module diamond_hole(size=6, th=plate_th+2) {
    rotate([0,0,45]) cube([size, size, th], center=true);
}

module rounded_polygon(points, r=2) {
    union() {
        linear_extrude(height=plate_th, center=true)
            offset(r=r) offset(delta=-r)
                polygon(points=points);
    }
}

module mounting_plate() {
    pts = [
        [-50,-35],
        [-20,-35],
        [-20,-45],
        [ 10,-45],
        [ 10,-35],
        [ 50,-35],
        [ 50,  0],
        [ 35,  0],
        [ 35, 35],
        [  0, 35],
        [  0, 45],
        [-30, 45],
        [-30, 35],
        [-50, 35]
    ];

    difference() {
        rounded_polygon(pts, r=3);

        // Group A (left)
        translate([-28, -10, 0]) diamond_hole(size=6);
        translate([-28,  10, 0]) diamond_hole(size=6);
        translate([-10,   0, 0]) diamond_hole(size=6);

        // Group B (right)
        translate([ 10, -10, 0]) diamond_hole(size=6);
        translate([ 10,  10, 0]) diamond_hole(size=6);
        translate([ 28,   0, 0]) diamond_hole(size=6);
    }
}

mounting_plate();

$fn=128;

outer_r = 20;
band_w = 6;
inner_r = outer_r - band_w;

thk = 3;

gap_deg = 55;
start_deg = gap_deg/2;
end_deg = 360 - gap_deg/2;

end_round_r = band_w/2;
bulb_r = band_w*0.75;

module ring_band_2d(){
    difference(){
        circle(r=outer_r);
        circle(r=inner_r);
    }
}

module sector_mask_2d(a1, a2, r){
    polygon(points=concat([[0,0]],
        [for (a=[a1:1:a2]) [r*cos(a), r*sin(a)]],
        [[r*cos(a2), r*sin(a2)]]
    ));
}

module c_clip_2d(){
    union(){
        intersection(){
            ring_band_2d();
            sector_mask_2d(start_deg, end_deg, outer_r+band_w*2);
        }
        for (a=[start_deg, end_deg]){
            translate([ (outer_r - band_w/2)*cos(a), (outer_r - band_w/2)*sin(a) ])
                circle(r=end_round_r);
        }
        translate([ (outer_r - band_w/2)*cos(start_deg), (outer_r - band_w/2)*sin(start_deg) ])
            circle(r=bulb_r);
    }
}

linear_extrude(height=thk, center=true, convexity=10)
    c_clip_2d();

$fn=96;

shaft_d = 20;
shaft_len = 60;

collar_af = 40;          // across flats
collar_thk = 20;

module shaft(d, l){
    cylinder(d=d, h=l, center=true);
}

module hex_collar(af, thk){
    r = af / sqrt(3);    // circumradius for given across-flats
    cylinder(r=r, h=thk, center=true, $fn=6);
}

union(){
    shaft(shaft_d, shaft_len);
    hex_collar(collar_af, collar_thk);
}
